package com.example.waterfilter;
import android.app.*;import android.content.*;import android.os.Build;
public class ReminderReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent i){String title=i.getStringExtra("title");String msg=i.getStringExtra("message");Intent open=new Intent(c,MainActivity.class);PendingIntent tap=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"filter_reminders"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title==null?"متابع فلتر المياه":title).setContentText(msg==null?"راجع موعد تغيير الشمعة":msg).setStyle(new Notification.BigTextStyle().bigText(msg)).setAutoCancel(true).setContentIntent(tap);if(Build.VERSION.SDK_INT<26)b.setPriority(Notification.PRIORITY_HIGH);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(i.getIntExtra("id",1),b.build());}}
